{"command": "cd /work/workspace/deliverable && python3 - <<'EOF'
import json, re
d = json.load(open('achados.json'))
for i,a in enumerate(d):
    if 'cláusula 19' in a['achado']:
        a['por_que_importa'] += " Resposta do cliente (25/10): a venda ainda NÃO foi comunicada à Horizonte — não há anuência obtida, nem informal; e a cláusula 19 exige consentimento prévio e expresso da pessoa jurídica ('jurídico duro'), não a amizade com o diretor. Sem a anuência, o fechamento destrói 31% da receita + multa de 20% do saldo."
        a['solucao'] = "Pedir a anuência já (carta à Horizonte assinada por quem tenha poderes), como condição precedente do fechamento ou com data-limite + resolução sem multa; preparar contraproposta (garantias/penalização) para o jurídico deles. Alternativa a preço: descontar o valor esperado da multa/contrato se a anuência falhar. Nunca fechar sem ela nem comunicada a operação sem plano de reação."
    if 'engenheiros' in a['achado'] or ('PJ' in a['achado'] and '11' in a['achado']):
        a['por_que_importa'] += " Resposta do cliente (25/10): '9h-18h, exclusivos, com gestor' confirma TODOS os pressupostos fáticos do vínculo (habitualidade, exclusividade, subordinação); 'sempre foi assim' é confissão de habitualidade desde a origem — a exposição é máxima e antiga (prescrição atingindo só os últimos 5 anos, mas com passivo por todo o período remanescente)."
    if 'CND federal POSITIVA' in a['achado']:
        a['por_que_importa'] += " Resposta do cliente (25/10): 'não parcelamos porque discordamos' = débito em cobrança SEM garantia e SEM suspensão de exigibilidade (discussão administrativa sem depósito/penhora não suspende — ponto de prática, não verificado na biblioteca); a CND permanece positiva e encargos correm sobre os R$ 310 mil."
        a['solucao'] = "Indenização específica fiscal com base em PIOR cenário (principal R$ 310 mil + encargos, não só o principal; 'uns 310 mil' é estimativa — confirmar valor inscrito); pagamento, parcelamento com garantia, ou desconto de preço equivalente ANTES da comunicação prévia a Sorocaba (a comunicação denuncia a irregularidade se vier primeiro); eventual procedência da discussão fiscal em favor da Vértice credita os vendedores (sem duplicidade)."
json.dump(d, open('achados.json','w'), ensure_ascii=False, indent=2)
# re-validate
d2 = json.load(open('achados.json'))
valid = {'anuencia','preco','indenizacao','prazo','nenhum'}
assert all(a['efeito'] in valid for a in d2), 'efeito invalido'
assert all(set(a) == {'achado','onde','por_que_importa','efeito','solucao'} for a in d2), 'schema'
print('ok', len(d2), 'achados; schema e efeito validos')
EOF"}
